const items = $input.all();
const config = $('Config: Signal Intelligence').first().json;

let allSignals = [];
const sourcesRead = [];

for (const item of items) {
  const source = item.json.source || 'unknown';
  const status = item.json.status || 'empty';

  if (status === 'error') {
    console.log(`Source ${source} returned error — skipping`);
    continue;
  }

  sourcesRead.push(source);

  let signals = item.json.signals || [];
  if (typeof signals === 'string') {
    try {
      signals = JSON.parse(signals);
    } catch(e) {
      console.log(`Failed to parse signals from ${source}: ${e.message}`);
      signals = [];
    }
  }

  for (const signal of signals) {
    allSignals.push({
      ...signal,
      _source: source,
      _dateRange: item.json.dateRange || ''
    });
  }
}

let formattedSignals = `Total signals: ${allSignals.length}\n`;
formattedSignals += `Sources: ${sourcesRead.join(', ')}\n`;
formattedSignals += `Date range: ${config.dateLastMonday} to ${config.dateToday}\n\n`;
formattedSignals += JSON.stringify(allSignals, null, 2);

return [{
  json: {
    allSignals,
    formattedSignals,
    totalSignals: allSignals.length,
    sourcesRead,
    dateToday: config.dateToday,
    dateLastMonday: config.dateLastMonday
  }
}];

const blocks = $('Fetch: Universal Distiller Prompt').first().json.results || [];
const collated = $('Collate: All Signals').first().json;

let distillerPrompt = '';
let inDistillerSection = false;

for (const block of blocks) {
  if (block.type === 'heading_2') {
    const text = block.heading_2?.rich_text?.[0]?.plain_text || '';
    if (text.includes('Universal Distiller Prompt')) {
      inDistillerSection = true;
      continue;
    }
    if (inDistillerSection) break;
  }
  if (inDistillerSection && block.type === 'code') {
    distillerPrompt = block.code?.rich_text?.map(r => r.plain_text).join('') || '';
    break;
  }
}

if (!distillerPrompt) {
  distillerPrompt = 'ERROR: Universal Distiller Prompt not found in Prompt Library';
}

const finalPrompt = distillerPrompt
  .replace('[all collector outputs injected here]', collated.formattedSignals || 'No signals found.')
  .replace('multiple sources', `${collated.sourcesRead?.length || 0} sources (${collated.sourcesRead?.join(', ')})`);

return [{
  json: {
    userMessage: finalPrompt,
    totalSignals: collated.totalSignals,
    sourcesRead: collated.sourcesRead,
    dateToday: collated.dateToday,
    dateLastMonday: collated.dateLastMonday
  }
}];

const response = $input.first().json;
const raw = response.content?.[0]?.text || '';
const context = $('Build: Distiller Context').first().json;

const clean = raw
  .replace(/^```json\n?/, '')
  .replace(/\n?```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    digest: {
      week: `${context.dateLastMonday} to ${context.dateToday}`,
      totalSignals: 0,
      highConfidence: 0,
      mediumConfidence: 0,
      lowConfidence: 0,
      sourcesRead: context.sourcesRead || []
    },
    signals: [],
    parse_error: e.message
  };
}

const digest = parsed.digest || {};
const signals = parsed.signals || [];

let formattedContext = `=== SIGNAL INTELLIGENCE DIGEST ===\n`;
formattedContext += `Week: ${digest.week || context.dateLastMonday + ' to ' + context.dateToday}\n`;
formattedContext += `Sources: ${(digest.sourcesRead || []).join(', ')}\n`;
formattedContext += `Total signals: ${digest.totalSignals || signals.length}\n`;
formattedContext += `High confidence: ${digest.highConfidence || signals.filter(s => s.confidence === 'high').length}\n`;
formattedContext += `Medium confidence: ${digest.mediumConfidence || signals.filter(s => s.confidence === 'medium').length}\n\n`;

const high = signals.filter(s => s.confidence === 'high');
const medium = signals.filter(s => s.confidence === 'medium');
const low = signals.filter(s => s.confidence === 'low');

if (high.length > 0) {
  formattedContext += `## 🔴 HIGH CONFIDENCE SIGNALS\n\n`;
  for (const s of high) {
    formattedContext += `### ${s.content}\n`;
    formattedContext += `Type: ${s.type} | Product: ${s.product}\n`;
    for (const src of (s.sources || [])) {
      formattedContext += `Source: ${src.source} — "${src.evidence}"\n`;
      if (src.url) formattedContext += `URL: ${src.url}\n`;
    }
    if (s.contentOpportunity) {
      formattedContext += `\n💡 Content idea: ${s.contentOpportunity.title}\n`;
      formattedContext += `Format: ${s.contentOpportunity.format} | ICP: ${s.contentOpportunity.icp}\n`;
      formattedContext += `Angle: ${s.contentOpportunity.angle}\n`;
      formattedContext += `Why now: ${s.contentOpportunity.whyNow}\n`;
    }
    formattedContext += `\n`;
  }
}

if (medium.length > 0) {
  formattedContext += `## 🟡 MEDIUM CONFIDENCE SIGNALS\n\n`;
  for (const s of medium) {
    formattedContext += `### ${s.content}\n`;
    formattedContext += `Type: ${s.type} | Product: ${s.product}\n`;
    for (const src of (s.sources || [])) {
      formattedContext += `Source: ${src.source} — "${src.evidence}"\n`;
      if (src.url) formattedContext += `URL: ${src.url}\n`;
    }
    if (s.contentOpportunity) {
      formattedContext += `\n💡 Content idea: ${s.contentOpportunity.title}\n`;
      formattedContext += `Format: ${s.contentOpportunity.format} | ICP: ${s.contentOpportunity.icp}\n`;
      formattedContext += `Angle: ${s.contentOpportunity.angle}\n`;
    }
    formattedContext += `\n`;
  }
}

if (low.length > 0) {
  formattedContext += `## ⚪ LOW CONFIDENCE SIGNALS (surface only)\n\n`;
  for (const s of low) {
    formattedContext += `- ${s.content} [${s.product}] — ${s.type}\n`;
  }
}

return [{
  json: {
    signalDigestContext: formattedContext,
    rawSignals: parsed,
    totalSignals: signals.length,
    highConfidence: high.length,
    mediumConfidence: medium.length,
    lowConfidence: low.length,
    sourcesRead: context.sourcesRead || []
  }
}];
